import * as rt from '@midnight-ntwrk/compact-runtime';
import { Contract, ledger, pureCircuits } from './out/contract/index.js';
const sk = (b)=>new Uint8Array(32).fill(b);
const mk = (b)=>new Contract({ secretKey: (ctx)=>[ctx.privateState, sk(b)] });
const A=pureCircuits.publicKey(sk(1)), B=pureCircuits.publicKey(sk(2));
const ca=mk(1), cb=mk(2);
const init = await ca.initialState(rt.createConstructorContext({}, '0'.repeat(64)));
let state = init.currentContractState.data;
const addr = rt.sampleContractAddress ? rt.sampleContractAddress() : '0'.repeat(64);
const hex=(k)=>Buffer.from(k).toString('hex').slice(0,6);
const show=(l)=>{const s=ledger(state);console.log(l.padEnd(22),'supply',s.totalSupply,[...s.balances].map(([k,v])=>[hex(k),v]).join(' | '));};
const run=async (c,n,...a)=>{
  const ctx = rt.createCircuitContext({circuitId:n,contractAddress:addr,coinPublicKeyOrZswapState:init.currentZswapLocalState.coinPublicKey,contractState:state,privateState:{}});
  const r=await c.impureCircuits[n](ctx,...a);
  if(!globalThis.dbg){globalThis.dbg=1;console.log(Object.keys(r.context),Object.keys(r.context.callContext||{}))}
  state = r.context.callContext.currentQueryContext.state; return r;};
const call=async (c,n,...a)=>{try{await run(c,n,...a);show(n)}catch(e){console.log(n,'FAILS:',e.message)}};
console.log('A=',hex(A),'B=',hex(B)); show('init (admin=A)');
await call(cb,'mint',B,10n);
await call(ca,'mint',B,100n);
await call(cb,'transfer',A,30n);
await call(cb,'transfer',A,500n);
await call(cb,'burn',20n);
await call(cb,'burn',500n);
await call(cb,'transfer',B,10n);
console.log('balanceOf B', (await run(cb,'balanceOf',B)).result, 'unknown', (await run(cb,'balanceOf',sk(9))).result);
